 app:'GH',
 apps:[{id:'GH',n:'GitHub',d:'Deploys, PRs, failed checks',to:'#dev-team',tier:'Digest',c:'#2d262d',by:'Momina · 3 Sep',acc:'Read repos, post messages',on:1},{id:'FG',n:'Figma',d:'File updates and comments',to:'Team notes',tier:'Digest',c:'#a259ff',by:'Syed · 8 Sep',acc:'Read files, post comments',on:1},{id:'UP',n:'Uptime',d:'Site down alerts',to:'#dev-team',tier:'Urgent',c:'#c0392b',by:'Momina · 1 Sep',acc:'Post alerts',on:1},{id:'GC',n:'Google Calendar',d:'Huddles and meetings',to:'Home',tier:'Normal',c:'#c63cc4',by:'Ahsan · 1 Sep',acc:'Read and create events',on:1},{id:'LN',n:'Linear',d:'Issue status changes',to:'#dev-team',tier:'Digest',c:'#5e6ad2',by:'Momina · 12 Sep',acc:'Read issues',on:1},{id:'XR',n:'Xero',d:'Invoices sent and paid',to:'Team notes',tier:'Digest',c:'#c736c4',by:'Ahsan · 20 Sep',acc:'Read invoices',on:1}],
