const ROUTES=['signup','setup','channels','dms','invite','client','schedule','decisions','agents','apps'];

/* ---------- helpers ---------- */
let tt;
function toast(t,undo){const el=document.getElementById('toast');el.innerHTML=`<span>${t}</span>${undo?'<button data-act="undo">Undo</button><i>10s</i>':''}`;el.classList.add('on');S._undo=undo||null;clearTimeout(tt);tt=setTimeout(()=>{el.classList.remove('on');S._undo=null},undo?6000:2600);}
function go(r){if(!ROUTES.includes(r))return;S.route=r;S.sideOpen=false;S.menu=null;if(location.hash.slice(1)!==r)history.replaceState(null,'','#'+r);try{parent.postMessage({seekRoute:r},'*')}catch(e){}render();document.querySelector('.feed,.dl,.pg,.inv,.auth')?.scrollTo?.(0,0);}
const rail=a=>`<nav class="rail">${['C','K'].map(w=>`<button class="wsb ${S.wsId===w?'on':''}" data-act="wsSwitch" data-arg="${w}" title="${WS[w].name}">${w}</button>`).join('')}<button class="wsb add" data-act="toast" data-arg="Create or join another workspace">＋</button><span class="sep"></span>${[['channels','team','Team'],['dms','dm','DMs',1],['client','cl','Clients',1],['schedule','mt','Meetings'],['decisions','dc','Decisions'],['agents','ap','Apps']].map(([r,i,l,d])=>`<button class="ri ${a===r||(a==='apps'&&r==='agents')?'on':''}" data-go="${r}">${svg(i)}${l}${d?'<span class="dot"></span>':''}</button>`).join('')}<button class="me" data-act="profile" aria-label="Your profile">${av('AH',34)}<span class="st ${S.status.k}"></span></button></nav>`;
