const mh=(title,sub,right,extra)=>`<div class="mh"><button class="menu" data-act="side" aria-label="Menu">☰</button><span class="mlogo" aria-hidden="true">S</span><div class="tt"><b>${title}</b><small>${sub}</small></div>${right||''}<button class="mprof" data-act="profile" aria-label="Your profile">${av('AH',32)}<span class="st ${S.status.k}"></span></button></div>${extra||''}`;
const tbar=()=>`<header class="tbar"><span class="slogo"><i>S</i><b>Seek</b><small>by Convertt</small></span><button class="tthm" data-act="brand" title="Theme and branding"><span class="sw3"><i style="background:var(--sbg)"></i><i style="background:var(--body)"></i><i style="background:var(--v)"></i></span>Theme</button><button class="tsearch" data-act="pal">⌕ <span>Search ${WS[S.wsId].name}</span><kbd>⌘K</kbd></button><div class="tr"><button class="tmode" data-act="modeToggle" title="Switch light / dark">${isDark()?'☀':'☾'}</button><button class="btn sm ghost" data-act="toast" data-arg="Help centre opens in a new tab">? Help</button><button class="btn sm ghost" data-act="toast" data-arg="3 new notifications">🔔<span class="badge" style="margin-left:2px">3</span></button><button class="tme" data-act="profile" aria-label="Your profile">${av('AH',30)}<span class="st ${S.status.k}"></span></button></div></header>`;
const shell=(a,sideH,mainH,paneH)=>`<div class="app ${S.sideOpen?'side-open':''} ${paneH?'has-pane':''}">${rail(S.route==='schedule'?'schedule':a)}${tbar()}${sideH}<main class="main">${mainH}</main>${paneH||''}</div>`;
function msgH(m,o={}){
 if(m.sep==='new')return '<div class="newsep">New</div>';
 if(m.type==='dec')return `<div class="dec ${m.gold?'gold':''} ${m.flash?'flash':''}"><div class="k"><span>DECISION</span>${m.gold?'<span class="tag gold">client</span>':''}</div><b>${esc(m.text)}</b><small>${esc(m.by)}</small><div class="a">${m.req?(S.approval==='open'?'<button class="btn sm gold" data-act="reqApp">Request formal approval</button>':'<span class="tag gold">Formal approval requested · due Thu</span>'):''}<button class="btn sm" data-go="decisions">Open log</button></div></div>`;
 const c=m.client;const rx=m.rx||{};
 return `<div class="msg ${m.ai?'ai':''} ${c?'client':''} ${S.menu===m.id?'menu':''} ${m.flash?'flash':''}" data-id="${m.id}">${av(m.who,36)}<div class="bd"><div class="nm"><b>${P[m.who][0]}</b>${m.ai?'<span class="tag ai">AI</span>':''}${c?'<span class="tag gold">client</span>':''}<small>${m.time}</small></div><div class="tx">${fmt(m.text)}</div>${m.src?`<a class="src" href="#" data-act="toast" data-arg="Sources: 9 messages in #launch-squad">${m.src}</a>`:''}${m.file?`<div class="file"><i>${m.file[0].split('.').pop().toUpperCase()}</i><div><b>${m.file[0]}</b><small>${m.file[1]}</small></div></div>`:''}${m.after?`<div class="tx" style="margin-top:6px">${fmt(m.after)}</div>`:''}${m.task?`<div class="task"><i></i>${esc(m.task)} <span class="tag v">task</span></div>`:''}${Object.keys(rx).length?`<div class="reacts">${Object.entries(rx).map(([e,n])=>`<button class="rx ${m.myrx===e?'me':''}" data-act="react" data-arg="${m.id}|${e}">${emoH(e)} ${n}</button>`).join('')}<button class="rx add" data-act="reactPick" data-arg="${m.id}" title="Add reaction">☺＋</button></div>`:''}${m.thread&&m.thread.length&&!o.inThread?`<button class="rlink" data-act="thread" data-arg="${m.id}">${m.thread.length} ${m.thread.length===1?'reply':'replies'} <small>last ${m.thread[m.thread.length-1].time}</small></button>`:''}${m.saved?'<div style="font-size:11.5px;color:var(--v);margin-top:4px;font-weight:600">★ Saved</div>':''}</div>${o.inThread?'':`<div class="mt"><button data-act="thread" data-arg="${m.id}">Reply</button><button data-act="reactPick" data-arg="${m.id}">React</button><button class="${m.saved?'on':''}" data-act="save" data-arg="${m.id}">${m.saved?'Saved':'Save'}</button><button data-act="more" data-arg="${m.id}">More</button></div>`}${S.menu===m.id?`<div class="mm"><button data-act="mkTask" data-arg="${m.id}">☐ Make task <kbd>T</kbd></button><button data-act="mkDec" data-arg="${m.id}">◇ Log decision <kbd>D</kbd></button><button data-act="toast" data-arg="Reminder set for tomorrow 09:00">⏰ Remind me <kbd>R</kbd></button><button data-act="toast" data-arg="Link copied">🔗 Copy link <kbd>L</kbd></button></div>`:''}</div>`;}
const comp=(ph,btn,gold,note)=>`<div class="comp ${gold?'gold':''}"><textarea id="ci" rows="1" placeholder="${esc(ph)}" data-enter="send"></textarea><div class="cr"><button class="ic" data-act="toast" data-arg="Attach a file">＋</button><button class="ic" data-act="emoji">☺</button><button class="ic" data-act="at">@</button>${note?`<small>${note}</small>`:''}<span class="sp"></span><button class="btn sm ghost" data-act="toast" data-arg="Scheduled for tomorrow 09:00">Send later</button><button class="btn sm ${gold?'gold':'pri'}" data-act="send">${btn}</button></div></div>`;
const find=(arr,id)=>arr.find(m=>m.id==id);

