V.setup=()=>{const w=S.ws;const slug=(w.name||'workspace').toLowerCase().replace(/[^a-z0-9]+/g,'')||'workspace';const cr=[['general','everyone'],['announcements','team news'],['random','off-topic']];if(w.use.includes('Client work'))cr.push(['Clients','ready for your first client']);if(w.use.includes('Tasks and decisions'))cr.push(['Decisions','log and approvals']);
return `<div class="auth"><div class="art"><div class="brand"><i>S</i><b>Seek</b><small>by Convertt</small></div><h2>Set up for how <em>your team works.</em></h2><p>Your answers decide which channels and spaces we create, and your notification defaults.</p><div class="pc" style="max-width:420px"><div class="r"><span class="av" style="width:34px;height:34px;background:var(--v);font-size:14px;border-radius:10px">${esc((w.name||'S')[0].toUpperCase())}</span><div><b>${esc(w.name||'Workspace')}</b><div style="color:var(--sb);font-size:12px" class="mono">${slug}.seek.app</div></div></div></div><div><div class="lbl" style="color:#c6a7c6;margin-bottom:8px">We'll create</div><div class="creates">${cr.map(([a,b])=>`<div>${a==='Clients'||a==='Decisions'?'◆':'#'} ${a}<small>${b}</small></div>`).join('')}</div></div><p style="font-size:13px">Notifications start on <b style="color:#fff">Balanced</b>.</p></div><div class="fm"><div class="mbrand"><span class="slogo"><i>S</i><b>Seek</b><small>by Convertt</small></span></div><div class="top">Signed in as ${esc(S.email)}</div><div class="in"><div class="steps"><span class="d"><i>✓</i>Account</span><hr><span class="d"><i>✓</i>Verify</span><hr><span class="c"><i>3</i>Workspace</span></div><div><h1>Set up your workspace</h1></div><p class="sub">A few questions so it is set up for how your team works.</p><div class="grid2"><div class="fld"><label>Workspace name</label><input class="inp" id="wsn" value="${esc(w.name)}" data-live="wsname"><em class="mono" id="slug">${slug}.seek.app</em></div><div class="fld"><label>Time zone</label><select class="inp" data-live="tz">${['Lahore (GMT+5)','London (GMT+1)','Dubai (GMT+4)','New York (GMT-4)'].map(z=>`<option ${z===w.tz?'selected':''}>${z}</option>`).join('')}</select><em>For working hours and Focus.</em></div></div><div class="fld"><label>Team size</label><div class="chips">${['1–10','11–50','51–200','200+'].map(s=>`<button class="chip ${w.size===s?'on':''}" data-act="size" data-arg="${s}">${s}</button>`).join('')}</div></div><div class="fld"><label>How will you use Seek?</label><div class="chips">${['Team chat','Client work','Tasks and decisions'].map(s=>`<button class="chip ${w.use.includes(s)?'on':''}" data-act="use" data-arg="${s}">${w.use.includes(s)?'✓ ':''}${s}</button>`).join('')}</div></div><div class="fld"><label>Invite teammates <span style="color:var(--sb);font-weight:400">(optional)</span></label><div class="tagin">${w.invites.map((e,i)=>`<span>${esc(e)}<button data-act="rmInv" data-arg="${i}" aria-label="Remove">×</button></span>`).join('')}<input id="invIn" placeholder="Add email, press Enter" data-enter="addInv"></div></div><button class="btn lg pri" data-act="finishSetup">Continue to #general</button><p class="fine">🔒 Secure sign-in · Your data is encrypted</p></div></div></div>`;};
V.channels=()=>{const c=S.channels.find(x=>x.id===S.ch);const ms=S.msgs[S.ch];const th=S.thread&&find(ms,S.thread);
 const sideH=side('Convertt','Team · 12 channels · your team only','<button class="btn sm" data-act="newCh">＋</button>',`<div class="sg lbl">Channels</div>${S.channels.map(x=>`<button class="si ${x.id===S.ch?'on':''} ${x.n?'unread':''}" data-act="ch" data-arg="${x.id}"><span class="h">#</span><span class="x"><b>${x.id}</b></span>${x.n?`<span class="badge">${x.n}</span>`:x.tier?`<span class="tag">${x.tier}</span>`:''}</button>`).join('')}<button class="si" data-act="toast" data-arg="Browse all 12 channels">＋ Browse channels</button><div class="sg lbl">Starred</div><button class="si" data-act="ch" data-arg="launch-squad"><span class="h">★</span><span class="x"><b>launch-squad</b><small>pinned brief</small></span></button>`);
 const tabs=`<div class="tabs">${['Messages','Files','Canvas','Pins'].map(t=>`<button class="tb ${S.chTab===t?'on':''}" data-act="chTab" data-arg="${t}">${t}</button>`).join('')}</div>`;
 let body;if(S.chTab==='Messages')body=`<div class="feed" id="feed"><div class="daysep">Today</div>${ms.map(m=>msgH(m)).join('')}</div>${S.ch==='launch-squad'&&!S.seenNew?'<button class="jump" data-act="jump">↓ 2 new messages</button>':''}${comp('Message #'+S.ch,'Send')}`;
 else if(S.chTab==='Files')body=`<div class="pg">${[['staging-home.png','Momina · 1.2 MB · today'],['hero-options.pdf','Ahsan · 4 MB · Thu'],['sitemap-v2.fig','Syed · Figma · Wed']].map(f=>`<div class="file" style="max-width:none"><i>${f[0].split('.').pop().toUpperCase()}</i><div style="flex:1"><b>${f[0]}</b><small>${f[1]}</small></div><button class="btn sm" data-act="toast" data-arg="Opening ${f[0]}">Open</button></div>`).join('')}</div>`;
 else if(S.chTab==='Canvas')body=`<div class="pg"><div class="card"><div class="ct"><b>Launch brief</b><span class="tag v">Pinned</span></div><p style="margin:0;color:var(--mu)">Goal: relaunch hollowbright.com on Wednesday 09:00 London. Owners: Syed (design), Momina (build), Ahsan (client).</p></div></div>`;
 else body=`<div class="pg"><div class="dec" style="margin:0"><div class="k"><span>PINNED</span></div><b>Launch brief · Wednesday 09:00 London</b><small>Pinned by Ahsan</small></div></div>`;
 const pane=th?`<aside class="pane"><div class="ph"><div style="flex:1"><b>Thread</b><small>${esc(th.text.slice(0,34))}…</small></div><button class="x" data-act="closeThread">×</button></div><div class="pb">${msgH(th,{inThread:1})}<div class="daysep" style="margin:0">${th.thread.length||'No'} ${th.thread.length===1?'reply':'replies'}</div>${th.thread.map((r,i)=>msgH({...r,id:'t'+i},{inThread:1})).join('')}</div><div class="comp" style="margin:0 12px 12px"><textarea id="ti" rows="1" placeholder="Reply in thread" data-enter="treply"></textarea><div class="cr"><label style="font-size:12px;color:var(--sb);display:flex;gap:6px;align-items:center"><input type="checkbox" id="alsoCh"> Also send to the channel</label><span class="sp"></span><button class="btn sm pri" data-act="treply">Reply</button></div></div></aside>`:'';
 return shell('channels',sideH,mh('# '+S.ch,c.desc,`<span class="stack hide-m">${av('SY',26)}${av('MO',26)}${av('AH',26)}</span><button class="btn sm hide-m" data-act="notif">🔔 ${S.notif||'Normal'}</button><button class="btn sm" data-act="huddle">🎧 Huddle</button>`,tabs)+body,pane);};
V.dms=()=>{const d=S.dms[S.dm];const p=P[S.dm];
 const sideH=side('DMs','private conversations','<button class="btn sm" data-act="toast" data-arg="Pick people to message">✎</button>',`<div class="sg lbl">Recent</div>${Object.entries(S.dms).map(([k,x])=>`<button class="si ${k===S.dm?'on':''} ${x.n?'unread':''}" data-act="dm" data-arg="${k}">${av(k,30)}<span class="x"><b>${P[k][0]}${k==='ZA'?' (design intern)':''}</b><small>${esc(x.last)}</small></span>${x.n?`<span class="badge">${x.n}</span>`:''}</button>`).join('')}<button class="si" data-act="toast" data-arg="Group DM: Syed, Momina">${av('SY',30)}<span class="x"><b>Syed, Momina</b><small>Friday lunch?</small></span></button>`);
 const main=mh(p[0],`${p[2]} · available · 14:10 in Lahore`,`<button class="btn sm" data-act="huddle">🎧 Huddle</button><button class="btn sm" data-act="pane">ⓘ</button>`,`<div class="tabs">${['Messages','Files','Pins'].map((t,i)=>`<button class="tb ${i===0?'on':''}" data-act="toast" data-arg="${t}">${t}</button>`).join('')}</div>`)+`<div class="feed" id="feed"><div class="banner v">🔒 This conversation is just between you and ${p[0]}.</div>${d.msgs.map(m=>msgH(m)).join('')}</div>${comp('Message '+p[0],'Send')}`;
 const pane=S.paneOpen?`<aside class="pane"><div class="ph"><b>Profile</b><button class="x" data-act="pane">×</button></div><div class="pb"><div style="display:flex;flex-direction:column;align-items:center;gap:8px;text-align:center">${av(S.dm,72)}<div><b style="font-size:17px">${p[0]} ${S.dm==='MO'?'Omar':''}</b><div style="color:var(--sb);font-size:13px">${p[2]} · ${S.dm==='MO'?'she/her':'they/them'}</div></div><div style="display:flex;gap:8px"><button class="btn sm" data-act="huddle">Call</button><button class="btn sm" data-act="toast" data-arg="Muted for 1 hour">Mute</button></div></div><div class="kv"><div><span>Local time</span><b>14:10 Lahore</b></div><div><span>Hours</span><b>Mon–Fri 9–6</b></div><div><span>Status</span><b style="color:var(--ok)">● Available</b></div></div><div><div class="lbl" style="margin-bottom:8px">In common</div><div class="chips"><span class="tag"># launch-squad</span><span class="tag"># dev-team</span><span class="tag gold">Hollow & Bright</span><span class="tag gold">Acme Foods</span></div></div></div></aside>`:'';
 return shell('dms',sideH,main,pane);};
V.invite=()=>{const i=S.inv;const st=n=>i.step===n?'on':i.step>n?'':'dim';
 return `<div class="inv"><div class="hd"><button class="btn sm" data-go="client">← Clients</button><h1>Invite a client</h1><div class="steps">${['You send','Client email','Client joins'].map((t,n)=>`${n?'<hr>':''}<span class="${i.step>n+1?'d':i.step===n+1?'c':''}"><i>${i.step>n+1?'✓':n+1}</i><span class="hide-m">${t}</span></span>`).join('')}</div></div><div class="row"><div class="ip ${st(1)}"><div class="k"><b>1 · YOU SEND THE INVITE</b></div><div class="c"><div><b style="font-size:17px">Invite a client</b><div style="color:var(--mu);font-size:13px">They get their own private space.</div></div><div class="fld"><label>Client email</label><input class="inp" id="ie" value="${esc(i.email)}"></div><div class="fld"><label>Space name</label><input class="inp" id="isn" value="${esc(i.space)}"></div><div class="fld"><label>Welcome message <span style="color:var(--sb);font-weight:400">(optional)</span></label><textarea class="inp" id="im" rows="2">${esc(i.msg)}</textarea></div><div style="display:flex;gap:8px"><button class="btn" data-act="toast" data-arg="Invite link copied">🔗 Copy invite link</button><button class="btn pri" style="flex:1" data-act="sendInv">Send invite</button></div></div></div><div class="ip ${st(2)}"><div class="k"><b>2 · THE CLIENT GETS AN EMAIL</b><span class="tag">Inbox</span></div><div class="c email"><div class="fr"><span class="av" style="width:34px;height:34px;background:var(--v);border-radius:10px;font-size:14px">S</span><div><b style="font-size:13.5px;display:block">Ahsan at Convertt</b><small style="color:var(--sb)">to ${esc(i.email)}</small></div></div><h3>Ahsan invited you to ${esc(i.space)}</h3><p>${esc(i.msg||'Chat with the team, follow progress and approve work in one place.')}</p><button class="btn lg pri" data-act="join" ${i.step<2?'disabled':''}>Join now</button><p class="fine">No password. You'll get a sign-in code.</p></div></div><div class="ip ${st(3)}"><div class="k"><b>3 · THE CLIENT JOINS</b></div><div class="c" style="align-items:center;text-align:center"><span class="av" style="width:52px;height:52px;background:var(--gold);border-radius:14px;font-size:18px">HB</span><div><b style="font-size:13px;color:var(--sb)">${esc(i.space)} · Your project space</b><h3 style="margin:4px 0 0;font-size:21px">Welcome, Chris</h3></div><p style="margin:0;color:var(--mu)">Enter the 6-digit code we just emailed you.</p><div class="codes" id="codes">${[0,1,2,3,4,5].map(n=>`<input inputmode="numeric" maxlength="1" data-i="${n}" ${i.step<3?'disabled':''}>`).join('')}</div><button class="btn lg gold" data-act="openSpace" ${i.step<3?'disabled':''}>Open my space</button></div></div></div></div>`;};
V.client=()=>{const sp=S.spaces.find(s=>s.id===S.cs)||S.spaces[0];const team=S.cTab==='Team notes';const isHB=S.cs==='HB';
 const sideH=side('Clients','one space per client','<button class="btn sm" data-go="invite">＋ New</button>',`<div class="sg lbl">Client spaces</div>${S.spaces.map(s=>`<button class="si ${s.id===S.cs?'on':''}" data-act="space" data-arg="${s.id}"><span class="av" style="width:30px;height:30px;border-radius:8px;background:${s.id==='HB'?'#8a5300':s.id==='NL'?'#684068':s.id==='AF'?'#5c7c2b':'#7a4b8c'};font-size:11px">${s.id}</span><span class="x"><b>${s.n}</b><small>${s.d}</small></span><span class="tag ${s.w==='26h'?'red':''}">${s.w}</span></button>`).join('')}<div class="sg lbl">Overview</div><button class="si" data-act="toast" data-arg="All clients: 4 active">All clients</button>`);
 const tabs=`<div class="tabs">${['Client chat','Team notes','Status','Approvals','People'].map(t=>`<button class="tb ${S.cTab===t?'on':''} ${t==='Client chat'?'gold':''}" data-act="cTab" data-arg="${t}">${t}${t==='Team notes'?' <span class="badge">2</span>':''}${t==='Approvals'&&S.approval!=='done'?' <span class="badge" style="background:var(--gold)">1</span>':''}</button>`).join('')}</div>`;
 let body;
 if(!isHB)body=`<div class="empty"><b style="display:block;font-size:16px;color:var(--ink)">${sp.n}</b>${sp.d} · Client chat is quiet. <br><br><button class="btn" data-act="space" data-arg="HB">Open Hollow & Bright</button></div>`;
 else if(S.cTab==='Client chat'||team){const ms=S.cmsgs[S.cTab];body=`<div class="feed" id="feed">${team?'<div class="banner v">🔒 <span><b>Team notes</b> are private to your team. Chris and Priya never see this.</span></div>':'<div class="banner gold">👁 <span><b>Chris and Priya</b> see everything in Client chat. For internal discussion, use <a href="#" data-act="cTab" data-arg="Team notes" style="color:inherit;text-decoration:underline">Team notes</a>.</span></div>'}${ms.map(m=>msgH(m)).join('')}${S.meeting&&!team?`<div class="dec" style="box-shadow:inset 4px 0 0 var(--v)"><div class="k"><span>MEETING</span><span class="tag v">${esc(S.meeting.tool)}</span></div><b>${esc(S.meeting.title)} · ${esc(S.meeting.when)}</b><small>Invite sent to Chris and Priya with a calendar file</small></div>`:''}</div>${team?comp('Note for the team…','Send'):comp('Message Hollow & Bright…','Send to client',1,'Client chat · Visible to Chris and Priya')}`;}
 else if(S.cTab==='Approvals')body=`<div class="pg"><div class="card"><div class="ct"><b>Hero B · desktop v4 + mobile v1</b><span class="tag ${S.approval==='done'?'ok':'gold'}">${S.approval==='done'?'Approved':S.approval==='req'?'Requested':'Open'}</span></div><small style="color:var(--sb)">Approver: Chris · due Thursday</small><div style="display:flex;gap:8px">${S.approval==='done'?'<span class="tag ok">✓ Approved by Chris · logged as decision</span>':'<button class="btn sm" data-act="nudge">Nudge Chris</button><button class="btn sm gold" data-act="approveSim">Simulate: Chris approves</button>'}</div></div></div>`;
 else if(S.cTab==='Status')body=`<div class="pg"><div class="stats">${[['62%','complete'],['Wed','launch'],['1','open approval'],['26h','longest wait']].map(([a,b])=>`<div class="stat"><b>${a}</b><span>${b}</span></div>`).join('')}</div></div>`;
 else body=`<div class="pg"><div class="ppl">${['CH','PR','AH','MO'].map(k=>`<div>${av(k,34)}<span><b>${P[k][0]}</b><small>${k==='CH'||k==='PR'?P[k][2]:'team'}</small></span></div>`).join('')}</div></div>`;
 const wait=S.replied?'<div class="timer ok"><b>Replied ✓</b>Timer stopped when the team replied.</div>':'<div class="timer"><b>Reply target: 1 working day</b>Chris has waited 26h. The timer stops when anyone on the team replies.</div>';
 const pane=isHB&&S.paneOpen?`<aside class="pane"><div class="ph"><b>In this client space</b><button class="x" data-act="pane">×</button></div><div class="pb"><div class="ppl">${['CH','PR','AH','MO'].map(k=>`<div>${av(k,32)}<span><b>${P[k][0]}</b><small>${k==='CH'?'client · approver':k==='PR'?'client · copy':k==='AH'?'team · lead':'team'}</small></span></div>`).join('')}</div>${wait}<div class="card"><div class="ct"><b>Open approval</b><span class="tag ${S.approval==='done'?'ok':'gold'}">${S.approval==='done'?'Approved':'Due Thu'}</span></div><small style="color:var(--mu)">Hero B · desktop v4 + mobile v1<br>Chris · due Thursday</small>${S.approval==='done'?'':'<button class="btn sm" data-act="nudge">Nudge Chris</button>'}</div><button class="btn pri" data-go="schedule">▤ Schedule a call</button></div></aside>`:'';
 return shell('client',sideH,mh(`${sp.n}`,`Client space · ${sp.d.toLowerCase()}`,`<span class="stack hide-m">${av('CH',26)}${av('PR',26)}</span><button class="btn sm" data-go="schedule">▤ <span class="hide-m">Schedule</span></button><button class="btn sm" data-act="pane">ⓘ</button>`,isHB?tabs:'')+body,pane);};
V.schedule=()=>{const x=S.sched;const slots=[['Today','15:00 Lahore','11:00 London'],['Tomorrow','14:00 Lahore','10:00 London'],['Wed 14 Oct','16:00 Lahore','12:00 London']];
 return V.client()+`<div class="scrim" data-act="closeSched"><div class="modal" data-stop="1"><div class="mhd"><span class="av" style="width:34px;height:34px;border-radius:9px;background:var(--gold);font-size:12px">HB</span><b>Schedule a meeting with Hollow & Bright</b><button class="btn sm ghost" data-act="closeSched">✕</button></div><div class="mb"><div class="fld"><label>Title</label><input class="inp" id="stt" value="${esc(x.title)}"></div><div class="fld"><label>Who</label><div class="tagin"><span style="background:var(--golds);color:var(--gold)">Chris (client)</span><span style="background:var(--golds);color:var(--gold)">Priya (client)</span><span>Momina</span><input placeholder="Add people"></div></div><div class="fld"><label>Suggested times · inside everyone's working hours</label><div class="slots">${slots.map((s,i)=>`<button class="slot ${x.slot===i?'on':''}" data-act="slot" data-arg="${i}"><small>${s[0]}</small><b>${s[1]}</b><span>${s[2]}</span></button>`).join('')}</div><em><a href="#" data-act="toast" data-arg="Opens a calendar picker">Or pick another time</a> · 30 minutes</em></div><div class="fld"><label>Video</label><div class="chips">${['Google Meet','Zoom','Seek video','In person'].map(t=>`<button class="chip ${x.tool===t?'on':''}" data-act="tool" data-arg="${t}">${t}</button>`).join('')}</div></div><div class="fld"><label>Agenda</label><textarea class="inp" id="sag" rows="2">${esc(x.agenda)}</textarea></div><div class="trow"><div><b>Send the invite to the client's space and email</b><small>Includes a calendar file.</small></div><button class="sw ${x.send?'on':''}" data-act="sw" data-arg="send"></button></div><div class="trow"><div><b>Record and take AI notes</b><small>Chris and Priya are told when recording starts. Notes go to Team notes first; you choose what to share.</small></div><button class="sw ${x.rec?'on':''}" data-act="sw" data-arg="rec"></button></div></div><div class="mf"><button class="btn" data-act="closeSched">Cancel</button><button class="btn pri" data-act="doSched">Schedule and invite</button></div></div></div>`;};
V.decisions=()=>{const W=[['All','All channels',S.decs.length],['launch-squad','# launch-squad',S.decs.filter(d=>d.where==='launch-squad').length],['design','# design',1],['HB','Hollow & Bright',1]];const T=[['All','All types'],['dec','Decisions'],['appr','Approvals from clients']];
 const list=S.decs.filter(d=>(S.dWhere==='All'||d.where===S.dWhere)&&(S.dType==='All'||d.type===S.dType));
 const sideH=side('Decisions','agreements, with where they came from','',`<div class="sg lbl">Where</div>${W.map(([k,l,n])=>`<button class="si ${S.dWhere===k?'on':''}" data-act="dWhere" data-arg="${k}"><span class="x"><b>${l}</b></span><span class="tag">${n}</span></button>`).join('')}<div class="sg lbl">Type</div>${T.map(([k,l])=>`<button class="si ${S.dType===k?'on':''}" data-act="dType" data-arg="${k}"><span class="x"><b>${l}</b></span></button>`).join('')}`);
 const main=mh('Decisions','What the team agreed, who agreed it, and the message it came from.','<button class="btn sm" data-act="toast" data-arg="Exported decisions.csv">⇩ Export</button>')+`<div class="dl"><div class="intro"><p>Edit or undo a decision from its menu. Edited decisions keep their history.</p><span class="tag v">This week · ${list.length}</span></div>${list.length?list.map(d=>`<div class="dec ${d.client?'gold':''} ${d.old?'old':''}"><div class="k"><span>${d.old?'REPLACED':'DECISION'}</span>${d.client?'<span class="tag gold">client</span>':''}<small style="margin-left:auto">${d.time}</small></div><b>${esc(d.t)}</b><small>${esc(d.by)} · ${d.where==='HB'?'Hollow & Bright':'#'+d.where}</small><div class="a"><button class="btn sm" data-act="${d.old?'hist':'src'}" data-arg="${d.id}">${d.a}</button>${d.old?'':`<button class="btn sm ghost" data-act="editDec" data-arg="${d.id}">Edit</button>`}</div>${S.hist===d.id?`<div class="hist"><b style="color:var(--ink)">History</b><span>Fri 15:02 · "Deploy on Wednesday 17:00" logged by Ahsan</span><span>Mon 10:12 · Replaced by "Deploy moves to Thursday 11:00"</span></div>`:''}</div>`).join(''):'<div class="empty">No decisions match these filters.</div>'}<div class="how">${['Log one from any message: More, then Log decision, or press D.','Undo appears for a few seconds after logging.','Edit a decision to replace it. The old one stays in history.','Clients see decisions made in their Client chat; Team notes decisions stay private.'].map((t,i)=>`<div><i>${i+1}</i>${t}</div>`).join('')}</div></div>`;
 return shell('decisions',sideH,main);};
const appsSide=a=>side('Apps','connected tools and AI','',`<div class="sg lbl">Apps</div>${[['apps','All apps'],['x1','Automations'],['x2','What reaches clients']].map(([k,l])=>`<button class="si ${a===k?'on':''}" ${k==='apps'?'data-go="apps"':`data-act="toast" data-arg="${l}"`}><span class="x"><b>${l}</b></span></button>`).join('')}<div class="sg lbl">AI</div>${[['x3','Away assistant'],['agents','AI agents']].map(([k,l])=>`<button class="si ${a===k?'on':''}" ${k==='agents'?'data-go="agents"':`data-act="toast" data-arg="${l}"`}><span class="x"><b>${l}</b></span></button>`).join('')}`);
V.agents=()=>{const pa=S.pauseAll;
 const main=mh('AI agents','Each agent follows the same hard rules, keeps a log, and can be switched off.',`<button class="btn sm" data-act="log" data-arg="All agents">Agent log</button>`)+`<div class="pg"><div class="intro"><div><h2>Your agents</h2><p>${S.agents.filter(a=>a.on&&!pa).length} of ${S.agents.length} running</p></div><div class="pause ${pa?'on':''}"><div><b>${pa?'All AI paused':'Pause all AI'}</b><small>admins only</small></div><button class="sw ${pa?'on':''}" data-act="pauseAll" style="${pa?'background:var(--red)':''}"></button></div></div>${pa?'<div class="banner gold" style="margin:0">⏸ <span>All AI is paused for everyone. Agents keep their settings and resume when you turn this off.</span></div>':''}<div class="ag">${S.agents.map((a,i)=>`<div class="agc ${!a.on||pa?'off':''}"><div class="ct"><span class="ic">✦</span><div><b>${a.n}</b><small>${a.d}</small></div><button class="sw ${a.on&&!pa?'on':''}" data-act="agent" data-arg="${i}" ${pa?'disabled':''}></button></div><div class="tg"><span class="tag ai">${a.lv}</span><span class="tag ${a.sc.startsWith('Client')?'gold':''}">${a.sc}</span></div><div class="rules"><span>Never reads Team notes</span><span>Never approves</span><span>Shows sources</span><span>Posts via What reaches clients</span></div><div class="ft"><span>${pa?'Paused':a.on?a.st:'Off'}</span><button class="btn sm" data-act="log" data-arg="${a.n}">Log</button></div></div>`).join('')}<div class="agc later"><span class="tag">Later</span><b style="font-size:14.5px;color:var(--ink)">Build your own agent</b><small>Type, instructions, data, permissions, dry test.</small></div></div><div class="rulebox"><div class="card"><div class="ct"><b>Hard rules</b><span class="tag">Always on</span></div><ul><li>Never reads Team notes when talking to a client</li><li>Never approves, prices or promises dates</li><li>Always shows its sources</li><li>Posts to clients only through What reaches clients</li></ul></div><div class="card"><div class="ct"><b>Permission levels</b></div>${[['Suggest only','Shows a suggestion; a person acts.'],['Asks before acting','Prepares the action; a person approves.'],['Acts','Acts on its own inside the rules, and logs it.']].map(([a,b])=>`<div class="lv"><b>${a}</b><span>${b}</span></div>`).join('')}</div></div></div>`;
 const dr=S.logOf?`<div class="scrim" data-act="closeLog" style="background:rgba(28,14,28,.3)"></div><div class="drawer"><div class="ph"><div style="flex:1"><b>${esc(S.logOf)} · log</b><small>Every action, with sources</small></div><button class="x" data-act="closeLog">×</button></div><div class="pb"><div class="log">${[['09:30','Posted Monday standup in #launch-squad','Sources: 9 messages'],['09:12','Suggested task "Safari menu bug" → accepted by Ahsan','From Syed\'s message'],['Yesterday 22:40','Answered Chris overnight (client-visible content only)','Source: launch plan'],['Yesterday 17:05','Flagged mobile hero animation as out of scope','Source: SOW v2']].map(([t,a,b])=>`<div><small>${t}</small><b style="font-weight:600">${a}</b><small>${b}</small></div>`).join('')}</div></div></div>`:'';
 return shell('agents',appsSide('agents'),main)+dr;};
V.apps=()=>{const a=S.apps.find(x=>x.id===S.app);
 const main=mh('All apps','Every connected tool, where it posts and on which tier. Apps never post to clients.','<button class="btn sm pri" data-act="toast" data-arg="Opening the app directory">Browse directory</button>')+`<div class="pg"><div class="stats"><div class="stat"><b>${S.apps.filter(x=>x.on).length}</b><span>apps installed</span></div><div class="stat"><b>${S.apps.filter(x=>x.on&&x.tier==='Digest').length}</b><span>post quietly on Digest</span></div><div class="stat ok"><b>0</b><span>post to clients</span></div><div class="stat"><b>${S.reqs.length}</b><span>requests to review</span></div></div><div class="al">${S.apps.map(x=>`<button class="ar ${x.id===S.app?'on':''} ${x.on?'':'off'}" data-act="app" data-arg="${x.id}"><span class="lg" style="background:${x.on?x.c:'#c7bcc7'}">${x.id}</span><span class="x"><b>${x.n}</b><small>${x.d}</small></span><span class="w">Posts to ${x.to}</span><span class="tag ${x.tier==='Urgent'?'red':x.tier==='Normal'?'v':''}">${x.on?x.tier:'Off'}</span></button>`).join('')}</div><div class="banner v" style="margin:0">🛡 <span>Apps can't be given access to client spaces. Anything automatic that reaches a client is listed in <b>What reaches clients</b>.</span></div><div><div class="lbl" style="margin-bottom:8px">Requests</div><div class="al">${S.reqs.length?S.reqs.map(r=>`<div class="ar"><span class="lg" style="background:${r.c}">${r.id}</span><span class="x"><b>${r.n}</b><small>requested by ${r.by}</small></span><button class="btn sm" data-act="decline" data-arg="${r.id}">Decline</button><button class="btn sm pri" data-act="approve" data-arg="${r.id}">Approve</button></div>`).join(''):'<div class="empty" style="padding:16px">No requests to review.</div>'}</div></div></div>`;
 const pane=a&&S.paneOpen?`<aside class="pane"><div class="ph"><span class="ar" style="padding:0;width:auto;background:none"><span class="lg" style="background:${a.c}">${a.id}</span></span><div style="flex:1"><b>${a.n}</b><small>Installed by ${a.by}</small></div><button class="x" data-act="pane">×</button></div><div class="pb"><div class="kv"><div><span>Posts to</span><b>${a.to}</b></div><div><span>Tier</span><b><select class="tierSel" data-live="tier">${['Digest','Normal','Urgent'].map(t=>`<option ${t===a.tier?'selected':''}>${t}</option>`).join('')}</select></b></div><div><span>Access</span><b>${a.acc}</b></div><div><span>Status</span><b style="color:${a.on?'var(--ok)':'var(--sb)'}">${a.on?'● On':'Off'}</b></div></div><p style="margin:0;font-size:12.5px;color:var(--mu)">Digest waits for the next summary. Normal notifies as usual. Urgent can break through Focus.</p><button class="btn" data-act="toast" data-arg="Test post sent to ${a.to}">Send test post</button><button class="btn ${a.on?'danger':'pri'}" data-act="appOn">${a.on?'Turn off':'Turn on'}</button></div></aside>`:'';
 return shell('apps',appsSide('apps'),main,pane);};

