function mentionList(){const base=[['everyone','Notify everyone in this conversation','@'],['here','Notify people who are online','@']];let ks=['AH','SY','MO','ZA'];if(S.route==='client'||S.route==='schedule')ks=S.cTab==='Team notes'?['AH','SY','MO']:['CH','PR','AH','MO'];if(S.route==='dms')ks=[S.dm,'AH'];return base.map(b=>({k:null,n:b[0],d:b[1]})).concat(ks.map(k=>({k,n:P[k][0].split(' ')[0],full:P[k][0],d:P[k][2]+(k==='CH'||k==='PR'?' · client':'')})));}
let MN=null;
function mnClose(){document.querySelectorAll('.mnp').forEach(x=>x.remove());MN=null;}
function mnOpen(ta){const v=ta.value.slice(0,ta.selectionStart);const m=v.match(/(^|\s)@(\w*)$/);if(!m){mnClose();return;}const q=m[2].toLowerCase();const items=mentionList().filter(x=>x.n.toLowerCase().startsWith(q)||(x.full||'').toLowerCase().includes(q));if(!items.length){mnClose();return;}
 MN={ta,q,items,i:Math.min(MN&&MN.ta===ta?MN.i:0,items.length-1)};const comp=ta.closest('.comp');comp.style.position='relative';let box=comp.querySelector('.mnp');if(!box){box=document.createElement('div');box.className='mnp';comp.appendChild(box);}
 box.innerHTML='<div class="mnh">Mention someone</div>'+items.map((x,i)=>'<button type="button" class="mni'+(i===MN.i?' on':'')+'" data-mi="'+i+'">'+(x.k?av(x.k,26):'<span class="av" style="width:26px;height:26px;background:var(--soft);color:var(--v);font-size:13px">@</span>')+'<span class="x"><b>'+esc(x.k?x.full:'@'+x.n)+'</b><small>'+esc(x.d)+'</small></span>'+(x.k&&x.k!=='AH'?'<i class="pres"></i>':'')+'</button>').join('');}
function mnPick(i){if(!MN)return;const x=MN.items[i];const ta=MN.ta;const pos=ta.selectionStart;const before=ta.value.slice(0,pos).replace(/@(\w*)$/,'@'+x.n+' ');ta.value=before+ta.value.slice(pos);ta.focus();ta.setSelectionRange(before.length,before.length);mnClose();}
__on(document,'input',e=>{const t=e.target;if(t.tagName==='TEXTAREA'&&t.closest('.comp'))mnOpen(t);});
__on(document,'keydown',e=>{if(!MN||e.target!==MN.ta)return;if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();MN.i=(MN.i+(e.key==='ArrowDown'?1:-1)+MN.items.length)%MN.items.length;mnOpen(MN.ta);}else if(e.key==='Enter'||e.key==='Tab'){e.preventDefault();e.stopImmediatePropagation();mnPick(MN.i);}else if(e.key==='Escape'){mnClose();}},true);
__on(document,'mousedown',e=>{const b=e.target.closest('.mni');if(b){e.preventDefault();mnPick(+b.dataset.mi);return;}if(!e.target.closest('.mnp'))mnClose();});

