const EMO={Smileys:['😀','😃','😄','😁','😂','🤣','😊','🙂','😉','😍','😘','😎','🤩','🥳','🤔','🤨','😐','😅','😬','😴','😮','😢','😭','😡','🤯','🥲','🫡','🤗'],Gestures:['👍','👎','👏','🙌','🙏','💪','👋','🤝','✌️','🤞','👀','🫶','👌','☝️'],Work:['✅','❌','⚠️','💡','🚀','📌','📎','🗓️','⏰','📈','📉','🧪','🐛','🔒','💬','📣','🎯','🧩','🛠️','📝'],Fun:['🔥','🎉','❤️','💜','⭐','✨','🍕','☕','🎂','🌈','🏆','💯']};
S.custom=(()=>{try{return JSON.parse(localStorage.getItem('seekEmoji')||'[]')}catch(e){return[]}})();
S.recentE=(()=>{try{return JSON.parse(localStorage.getItem('seekRecentE')||'[]')}catch(e){return[]}})();
const cimg=n=>{const c=S.custom.find(x=>x.n===n);return c?'<img class="cemo" alt=":'+n+':" title=":'+n+':" src="'+c.src+'">':':'+n+':';};
const emoH=e=>e==='+1'?'👍':(e[0]===':'?cimg(e.slice(1,-1)):e);
let EP=null;
function epClose(){document.querySelectorAll('.emp').forEach(x=>x.remove());EP=null;}
function epOpen(target,anchor){epClose();EP={target,cat:'Smileys',q:''};const b=document.createElement('div');b.className='emp';b.addEventListener('mousedown',e=>{if(!e.target.closest('input'))e.preventDefault();});document.body.appendChild(b);EP.box=b;EP.anchor=anchor;epDraw();}
function epDraw(){const b=EP.box;const cats=['Recent'].concat(Object.keys(EMO)).concat(['Custom']);const q=EP.q.toLowerCase();
 let items;if(EP.cat==='Custom')items=S.custom.map(c=>({k:':'+c.n+':',h:'<img class="cemo lg" src="'+c.src+'">',t:c.n}));else if(EP.cat==='Recent')items=S.recentE.map(e=>({k:e,h:emoH(e),t:e}));else items=EMO[EP.cat].map(e=>({k:e,h:e,t:e}));
 if(q){items=Object.values(EMO).flat().map(e=>({k:e,h:e,t:e})).concat(S.custom.map(c=>({k:':'+c.n+':',h:'<img class="cemo lg" src="'+c.src+'">',t:c.n}))).filter(x=>x.t.toLowerCase().includes(q)||x.k.includes(q));}
 b.innerHTML='<div class="emh"><input class="inp" id="eq" placeholder="Search emoji and icons" value="'+esc(EP.q)+'"></div><div class="emt">'+cats.map(c=>'<button type="button" data-ec="'+c+'" class="'+(EP.cat===c&&!q?'on':'')+'">'+({Recent:'🕘',Smileys:'😀',Gestures:'👍',Work:'✅',Fun:'🎉',Custom:'★'}[c])+'<span>'+c+'</span></button>').join('')+'</div><div class="emg">'+(items.length?items.map(x=>'<button type="button" data-ek="'+esc(x.k)+'" title="'+esc(x.t)+'">'+x.h+'</button>').join(''):'<div class="empty" style="grid-column:1/-1;padding:18px">'+(EP.cat==='Custom'?'No custom icons yet. Upload your own below.':'Nothing here yet.')+'</div>')+'</div><div class="emf"><label class="btn sm"><input type="file" accept="image/*" id="eup" hidden>⬆ Add your emoji / icon</label>'+(EP.cat==='Custom'&&S.custom.length?'<button type="button" class="btn sm ghost danger" data-eclr="1">Clear custom</button>':'')+'</div>';
 const a=EP.anchor.getBoundingClientRect();const w=Math.min(340,innerWidth-16);b.style.width=w+'px';b.style.left=Math.max(8,Math.min(a.left,innerWidth-w-8))+'px';const h=b.offsetHeight;b.style.top=(a.top-h-8>8?a.top-h-8:Math.min(a.bottom+8,innerHeight-h-8))+'px';
 const qi=b.querySelector('#eq');qi.oninput=()=>{EP.q=qi.value;const pos=qi.selectionStart;epDraw();const n=EP.box.querySelector('#eq');n.focus();n.setSelectionRange(pos,pos);};
 b.querySelector('#eup').onchange=e=>{const f=e.target.files[0];if(!f)return;const r=new FileReader();r.onload=()=>{const img=new Image();img.onload=()=>{const cv=document.createElement('canvas');cv.width=cv.height=64;const x=cv.getContext('2d');const s=Math.min(img.width,img.height);x.drawImage(img,(img.width-s)/2,(img.height-s)/2,s,s,0,0,64,64);let n=(prompt('Name your emoji (letters, numbers, - or _)',f.name.replace(/\.[^.]+$/,'').toLowerCase().replace(/[^a-z0-9_-]+/g,'-'))||'').toLowerCase().replace(/[^a-z0-9_-]+/g,'-').replace(/^-+|-+$/g,'');if(!n)return;S.custom=S.custom.filter(c=>c.n!==n).concat([{n,src:cv.toDataURL('image/png')}]);try{localStorage.setItem('seekEmoji',JSON.stringify(S.custom))}catch(er){}EP.cat='Custom';EP.q='';epDraw();toast('Added :'+n+': to your emoji');};img.src=r.result;};r.readAsDataURL(f);};}
function epPick(k){const t=EP.target;S.recentE=[k].concat(S.recentE.filter(x=>x!==k)).slice(0,24);try{localStorage.setItem('seekRecentE',JSON.stringify(S.recentE))}catch(e){}
 if(t.type==='comp'){const ta=t.ta;const p=ta.selectionStart??ta.value.length;const ins=k+' ';ta.value=ta.value.slice(0,p)+ins+ta.value.slice(p);ta.focus();ta.setSelectionRange(p+ins.length,p+ins.length);epClose();}
 else{epClose();act('react',t.id+'|'+k);}}
__on(document,'click',e=>{if(!EP)return;const c=e.target.closest('[data-ec]');if(c){EP.cat=c.dataset.ec;EP.q='';epDraw();return;}const k=e.target.closest('[data-ek]');if(k){epPick(k.dataset.ek);return;}if(e.target.closest('[data-eclr]')){if(confirm('Remove all custom emoji?')){S.custom=[];localStorage.removeItem('seekEmoji');epDraw();}return;}if(!e.target.closest('.emp')&&!e.target.closest('[data-act="emoji"],[data-act="reactPick"]'))epClose();},true);
__on(window,'resize',()=>EP&&epClose());
const BRANDS=[['Aubergine','#4b154a'],['Lagoon','#0a566b'],['Indigo','#3f37c9'],['Ocean','#1264a3'],['Forest','#1f6b45'],['Crimson','#b3261e'],['Amber','#a15c00'],['Graphite','#2b2f36']];
function hexMix(h,k,to){const a=parseInt(h.slice(1),16),r=a>>16,g=a>>8&255,b=a&255,t=to==='w'?255:0;const m=v=>Math.round(v+(t-v)*k).toString(16).padStart(2,'0');return '#'+m(r)+m(g)+m(b);}
function applyBrand(h){const R=document.documentElement.style;R.setProperty('--v',h);R.setProperty('--vd',hexMix(h,.28,'b'));R.setProperty('--vs',hexMix(h,.88,'w'));R.setProperty('--rail',hexMix(h,.9,'w'));R.setProperty('--railln',hexMix(h,.78,'w'));S.brand=h;try{localStorage.setItem('seekBrand',h)}catch(e){}}
let BP=null;
function bpClose(){document.querySelectorAll('.bpop').forEach(x=>x.remove());BP=null;}
function bpOpen(anchor){bpClose();const b=document.createElement('div');b.className='bpop';BP=b;document.body.appendChild(b);bpDraw(anchor);}
function bpDraw(anchor){const b=BP;const t=S.theme;const sec=(k,title,sub)=>'<div class="bsec"><div class="bst"><b>'+title+'</b><small>'+sub+'</small></div><div class="bpg">'+THEMES[k].map(([n,h])=>'<button type="button" data-tk="'+k+'" data-tv="'+h+'" class="'+(t[k]===h?'on':'')+'"><span style="background:'+h+'"></span><em>'+n+'</em></button>').join('')+'</div><label class="bpc">Custom <input type="color" data-tc="'+k+'" value="'+t[k]+'"><code>'+t[k]+'</code></label></div>';b.innerHTML='<div class="bph"><b>Theme & branding</b><small>Sidebar, page and accent colours</small></div><div style="padding:0 14px 10px">'+modeSeg()+'</div><div class="bprev"><span style="background:'+t.side+'"><i></i><i></i><i></i></span><span style="background:'+t.body+'"><i style="background:'+t.acc+'"></i><i></i></span></div><div class="bscroll">'+sec('side','Sidebar','Left bar and channel list')+sec('body','Page','Background behind your content')+sec('acc','Accent','Buttons, highlights and links')+'</div><div class="bpf"><button type="button" class="btn sm ghost" data-breset="1">Reset</button><button type="button" class="btn sm pri" data-bdone="1">Done</button></div>';if(anchor){const a=anchor.getBoundingClientRect();const w=Math.min(340,innerWidth-16);b.style.width=w+'px';b.style.left=Math.max(8,Math.min(a.left,innerWidth-w-8))+'px';b.style.top=Math.max(8,Math.min(a.bottom+8,innerHeight-Math.min(b.offsetHeight,innerHeight-16)-8))+'px';}b.querySelectorAll('[data-tc]').forEach(inp=>inp.oninput=e=>{const k=inp.dataset.tc;applyTheme({...S.theme,[k]:inp.value});const top=b.style.top,left=b.style.left;const sc=b.querySelector('.bscroll').scrollTop;bpDraw();b.style.top=top;b.style.left=left;b.querySelector('.bscroll').scrollTop=sc;});}
__on(document,'click',e=>{if(!BP)return;const s=e.target.closest('[data-tk]');if(s){applyTheme({...S.theme,[s.dataset.tk]:s.dataset.tv});const top=BP.style.top,left=BP.style.left,sc=BP.querySelector('.bscroll').scrollTop;bpDraw();BP.style.top=top;BP.style.left=left;BP.querySelector('.bscroll').scrollTop=sc;render();return;}if(e.target.closest('[data-breset]')){applyTheme({side:'#3f0e40',body:'#f8f3ea',acc:'#611f69'});bpClose();render();toast('Theme reset');return;}if(e.target.closest('[data-bdone]')){bpClose();toast('Theme saved');return;}if(!e.target.closest('.bpop')&&!e.target.closest('[data-act="brand"]'))bpClose();},true);


